import threading
class Cache:
 def __init__(self):self.values={};self.guard=threading.Lock();self.locks={}
 def get(self,key,factory):
  with self.guard:lock=self.locks.setdefault(key,threading.Lock())
  with lock:
   if key not in self.values:self.values[key]=factory()
   return self.values[key]

def validate(request):
 if type(request)is not dict or set(request)!={'dependencies','workers','keys','rounds'}:raise ValueError('schema')
 deps=request['dependencies'];keys=request['keys']
 if type(deps)is not list or not 1<=len(deps)<=2 or any(type(x)is not str or x not in ('safe','legacy')for x in deps)or len(set(deps))!=len(deps):raise ValueError('dependencies')
 if type(request['workers'])is not int or not 2<=request['workers']<=4:raise ValueError('workers')
 if type(request['rounds'])is not int or not 1<=request['rounds']<=8:raise ValueError('rounds')
 if type(keys)is not list or not 1<=len(keys)<=8 or any(type(k)is not str or not 1<=len(k)<=32 for k in keys)or len(set(keys))!=len(keys):raise ValueError('keys')

def migrate(request,run_native):
 validate(request)
 ft=run_native('ft',request)
 if ft['status']=='passed'and ft['runtime']['Py_GIL_DISABLED']==1 and ft['gil_at_end']is False:
  return {'selected':'ft','reason':'compatible','ft':ft,'normal':None}
 reason='race'if ft['status']=='race_detected'else'unsupported'
 normal=run_native('normal',request)
 if normal['status']!='passed'or normal['runtime']['Py_GIL_DISABLED']!=0 or normal['gil_at_end']is not True:raise RuntimeError('traditional rollback failed')
 return {'selected':'normal','reason':reason,'ft':ft,'normal':normal}

