import argparse,json,pathlib,tempfile,sys
import task
def main(argv=None,runner=None):
 try:
  parser=argparse.ArgumentParser();parser.add_argument('--request',required=True);parser.add_argument('--output',required=True);args=parser.parse_args(argv)
  source=pathlib.Path(args.request);output=pathlib.Path(args.output)
  if output.exists()or output.is_symlink()or not output.parent.is_dir():raise ValueError('new output required')
  request=json.loads(source.read_text(encoding='utf-8'));task.validate(request)
  if runner is None:
   from checks.native_driver import Driver
   runner=Driver()
  result=task.migrate(request,runner)
  with tempfile.TemporaryDirectory(prefix='.ft025-',dir=output.parent)as temporary:
   stage=pathlib.Path(temporary)/'result';stage.mkdir()
   (stage/'ft_report.json').write_text(json.dumps(result['ft'],sort_keys=True),encoding='utf-8')
   if result['normal']is not None:(stage/'normal_report.json').write_text(json.dumps(result['normal'],sort_keys=True),encoding='utf-8')
   receipt={'selected':result['selected'],'reason':result['reason'],'normal_executable':result['normal']['runtime']['executable']if result['normal']else None,'normal_build_flag':result['normal']['runtime']['Py_GIL_DISABLED']if result['normal']else None,'baseline_sha256':result['normal']['candidate_import']['sha256']if result['normal']else None}
   (stage/'rollback_receipt.json').write_text(json.dumps(receipt,sort_keys=True),encoding='utf-8');stage.rename(output)
  print(json.dumps({'status':'complete','selected':result['selected']}));return 0
 except (ValueError,KeyError,TypeError,OSError,RuntimeError)as error:
  print(type(error).__name__+': '+str(error),file=sys.stderr);return 2
if __name__=='__main__':raise SystemExit(main())

